// Verifies X-DreamRue-Signature = hex HMAC-SHA256 of the *raw* JSON body, exactly
// as computed in infrastructure/webhooks/outbound-webhook.ts::signWebhookBody.
// Requires the Webhook node's Raw Body option (set above) so we sign the literal
// bytes the app sent, not a re-serialization of the parsed object — those can
// differ (key order, number formatting) even when they look identical.
const crypto = require('crypto');
const secret = $env.DREAMRUE_WEBHOOK_SHARED_SECRET;
const item = $input.first();
const rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body); // fallback if Raw Body isn't available on this n8n version — see workflow note
const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const provided = item.json.headers['x-dreamrue-signature'];
if (!provided || provided !== expected) {
  throw new Error('Invalid or missing x-dreamrue-signature header');
}
return [{ json: JSON.parse(rawBody) }];
